  ('mon_etablissement_id()', 'RPC_UTILISATEUR_AUTH_INTERNE', 'dc3ef839d2920fb33cf6d7b320842c10', 'RPC authenticated: identité/tenancy interne observée (auth.uid).'),
  ('mon_role()', 'RPC_UTILISATEUR_AUTH_INTERNE', 'cd693da03b2e8b39ba3530436ae71b95', 'RPC authenticated: identité/tenancy interne observée (auth.uid).'),
  ('peut_exercer(text,text,text)', 'RPC_UTILISATEUR_AUTH_INTERNE', '28d0bccc0fe45ca8a45f940f20040571', 'RPC authenticated de lecture/référentiel ou wrapper vers une RPC canonique; ACL et appelants recensés.');

DO $assert_explicit_security_definer_manifest$
DECLARE
  v_missing text;
  v_orphan text;
  v_hash_mismatch text;
  v_total integer;
BEGIN
  WITH current_exposed AS (
    SELECT p.oid::regprocedure::text AS signature,
           md5(p.prosrc) AS body_md5
      FROM pg_proc p
      JOIN pg_namespace n ON n.oid = p.pronamespace
     WHERE n.nspname = 'public'
       AND p.prosecdef IS TRUE
       AND p.prokind = 'f'
       AND (
         has_function_privilege('anon', p.oid, 'EXECUTE')
         OR has_function_privilege('authenticated', p.oid, 'EXECUTE')
         OR p.oid::regprocedure::text IN (
           'fn_doit_notifier(uuid,type_evenement_notification,canal_notification)',
           'fn_sms_doit_envoyer(uuid,text,integer)',
           'fn_generer_numero_contrat_safe(text)',
           'fn_conflit_planning_soignant(uuid,uuid)',
           'fn_calculer_score_matching(uuid,uuid)'
         )
       )
  )
  SELECT string_agg(c.signature, ', ' ORDER BY c.signature)
    INTO v_missing
    FROM current_exposed c
    LEFT JOIN private.security_definer_inventory i USING (signature)
   WHERE i.signature IS NULL;

  SELECT string_agg(i.signature, ', ' ORDER BY i.signature)
    INTO v_orphan
    FROM private.security_definer_inventory i
    LEFT JOIN (
      SELECT p.oid::regprocedure::text AS signature
        FROM pg_proc p
        JOIN pg_namespace n ON n.oid = p.pronamespace
       WHERE n.nspname = 'public'
         AND p.prosecdef IS TRUE
         AND p.prokind = 'f'
    ) c USING (signature)
   WHERE c.signature IS NULL;

  SELECT string_agg(i.signature, ', ' ORDER BY i.signature)
    INTO v_hash_mismatch
    FROM private.security_definer_inventory i
    JOIN pg_proc p ON p.oid::regprocedure::text = i.signature
    JOIN pg_namespace n ON n.oid = p.pronamespace
   WHERE n.nspname = 'public'
     AND md5(p.prosrc) <> i.definition_md5;

  SELECT count(*) INTO v_total
    FROM private.security_definer_inventory;

  IF v_missing IS NOT NULL THEN
    RAISE EXCEPTION 'SECURITY DEFINER non classées : %', v_missing;
  END IF;
  IF v_orphan IS NOT NULL THEN
    RAISE EXCEPTION 'Signatures SECURITY DEFINER obsolètes : %', v_orphan;
  END IF;
  IF v_hash_mismatch IS NOT NULL THEN
    RAISE EXCEPTION 'Corps SECURITY DEFINER modifiés sans revue : %', v_hash_mismatch;
  END IF;
  IF v_total <> 422 THEN
    RAISE EXCEPTION 'Manifest SECURITY DEFINER incomplet : %/422', v_total;
  END IF;
  IF (SELECT count(*) FROM private.security_definer_inventory WHERE categorie = 'RPC_UTILISATEUR_AUTH_INTERNE') <> 190 THEN
    RAISE EXCEPTION 'Compte RPC_UTILISATEUR_AUTH_INTERNE inattendu';
  END IF;
  IF (SELECT count(*) FROM private.security_definer_inventory WHERE categorie = 'ADMIN_EST_ADMIN_VALIDE') <> 117 THEN
    RAISE EXCEPTION 'Compte ADMIN_EST_ADMIN_VALIDE inattendu';
  END IF;
  IF (SELECT count(*) FROM private.security_definer_inventory WHERE categorie = 'MIXTE_TENANT_ADMIN') <> 103 THEN
    RAISE EXCEPTION 'Compte MIXTE_TENANT_ADMIN inattendu';
  END IF;
  IF (SELECT count(*) FROM private.security_definer_inventory WHERE categorie = 'PUBLIC_VOLONTAIRE') <> 7 THEN
    RAISE EXCEPTION 'Compte PUBLIC_VOLONTAIRE inattendu';
  END IF;
  IF (SELECT count(*) FROM private.security_definer_inventory WHERE categorie = 'SERVICE_ONLY_REVOQUE') <> 5 THEN
    RAISE EXCEPTION 'Compte SERVICE_ONLY_REVOQUE inattendu';
  END IF;
END
$assert_explicit_security_definer_manifest$;

COMMIT;
